contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    receive() external payable {}

    function run(address target, uint sendValue, bytes memory data) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= sendValue);
        require(target == address(this));
        uint depositsBefore = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint myBalBefore = address(this).balance;
        uint cBalBefore = address(c).balance;

        bool reverted;
        c.sendMoney(target, sendValue, data); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint depositsAfter = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint myBalAfter = address(this).balance;
        uint cBalAfter = address(c).balance;

        assert(depositsAfter == depositsBefore && (reverted ? (cBalAfter == cBalBefore && myBalAfter == myBalBefore) : (myBalAfter + cBalAfter == myBalBefore + cBalBefore)));
    }
}

