pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(address target, uint256 sendValue, bytes memory data) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= sendValue);
        target = address(this);
        uint256 depositsBefore;
        try c.depositsCount() returns (uint256 __r) { depositsBefore = __r; } catch { return; }
        uint myBalBefore = address(this).balance;
        uint cBalBefore = address(c).balance;
        bool reverted;
        try c.sendMoney(target, sendValue, data) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 depositsAfter;
        try c.depositsCount() returns (uint256 __r) { depositsAfter = __r; } catch { return; }
        uint myBalAfter = address(this).balance;
        uint cBalAfter = address(c).balance;
        assertTrue(depositsAfter == depositsBefore && (reverted ? (cBalAfter == cBalBefore && myBalAfter == myBalBefore) : (myBalAfter + cBalAfter == myBalBefore + cBalBefore)));
    }

    function testFuzz_run(address target, uint256 sendValue, bytes memory data) public {
        _run(target, sendValue, data);
    }

    receive() external payable {}
}
